const sourceCode = "import { Callout, Tabs, Steps } from \"nextra/components\";\nimport { Shield, Zap, Lock } from \"lucide-react\";\n\n# Privacy Protocol SDK\n\n**Privacy Protocol** is the modular privacy layer for the EVM. Powered by zero-knowledge proofs, it enables developers to seamlessly integrate privacy into any dApp without sacrificing composability.\n\n<Callout type=\"info\" emoji=\"👻\">\n  **New Release:** The SDK now supports **Arbitrum Stylus** and **Optimism**.\n  Check the [Changelog](/changelog) for details.\n</Callout>\n\n## Quick Start\n\nGet up and running in less than 5 minutes.\n\n<Tabs items={[\"npm\", \"yarn\", \"pnpm\"]}>\n  <Tabs.Tab>```bash npm install @ghostly/sdk @ghostly/react ```</Tabs.Tab>\n  <Tabs.Tab>```bash yarn add @ghostly/sdk @ghostly/react ```</Tabs.Tab>\n  <Tabs.Tab>```bash pnpm add @ghostly/sdk @ghostly/react ```</Tabs.Tab>\n</Tabs>\n\n## How It Works\n\n<Steps>\n### Install and Enable\nInstall the SDK to wrap standard wallets. Enable shielded transactions with zero changes to your backend logic.\n\n### Client-Side Proving\n\nThe SDK abstracts ZK complexity, generating local proofs (Noir/bb.js) to authorize intents without revealing the signer's identity.\n\n### Relayed Execution\n\nProofs are verified on-chain. The protocol executes calls to your contract via a fresh, **ephemeral proxy**.\n\n### Composable Settlement\n\nExecute standard logic (mint, swap). Outputs are automatically routed back to the user's shielded balance via the UTXO model.\n\n</Steps>\n\n## Next Steps\n\n<div className=\"grid grid-cols-1 md:grid-cols-2 gap-4 mt-8\">\n  <a\n    href=\"/docs/guides/integration\"\n    className=\"p-4 border rounded-lg hover:border-blue-500 transition-colors\"\n  >\n    <div className=\"flex items-center gap-2 font-bold mb-2\">\n      <Shield className=\"w-5 h-5\" /> Integration Guide\n    </div>\n    <p className=\"text-gray-500 text-sm\">\n      Learn how to add the `useShield` hook to your dApp.\n    </p>\n  </a>\n\n  <a\n    href=\"/docs/core-sdk\"\n    className=\"p-4 border rounded-lg hover:border-blue-500 transition-colors\"\n  >\n    <div className=\"flex items-center gap-2 font-bold mb-2\">\n      <Zap className=\"w-5 h-5\" /> Core SDK Reference\n    </div>\n    <p className=\"text-gray-500 text-sm\">\n      Low-level API for backend bots and scripts.\n    </p>\n  </a>\n</div>";
